// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmt, uint256 collectAmt) public {
        // Require caller is not the zero address and amounts are non-zero to make deposits/collects meaningful
        vm.assume(caller != address(0));
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > 0);
        // Ensure deposit does not overflow (safe206ish, solidity 0.8 checks)
        vm.assume(depositAmt <= type(uint256).max - 0);

        // Initialize the contract and set MinSum to a value <= depositAmt so that collect condition can be met
        c.SetMinSum(1);
        c.Initialized();

        // Fund caller and make deposit
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Record post-deposit balance to compute the invariant
        uint256 balanceAfterDeposit = c.balances(caller);

        // Only test collect if balance is non-zero and collectAmt is within balance and MinSum
        vm.assume(balanceAfterDeposit >= collectAmt);
        vm.assume(collectAmt <= balanceAfterDeposit);

        // Perform collect
        vm.prank(caller);
        // catch possible revert in Collect
        bool ok = true;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // If collect succeeded, final balance must be balanceAfterDeposit - collectAmt
        uint256 finalBalance = c.balances(caller);
        if (ok) {
            assertTrue(finalBalance == balanceAfterDeposit - collectAmt);
        }
    }
}

