pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Bound amounts to avoid overflow and ensure collect <= deposit
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // Set MinSum to 0 so any balance qualifies for Collect
        c.SetMinSum(0);
        // Set a dummy log file to avoid revert in AddMessage
        c.SetLogFile(address(this));
        c.Initialized();

        // Use a fresh EOA to avoid state interference
        address actor = address(uint160(uint256(keccak256(abi.encode(depositAmount, collectAmount)))));
        vm.deal(actor, depositAmount);

        // Deposit
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Collect
        vm.prank(actor);
        bool success;
        try c.Collect(collectAmount) {
            success = true;
        } catch {
            success = false;
        }

        // Rule: after depositing and collecting a valid amount, Collect must succeed
        assertTrue(success);
    }
}
