pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 minSum) public {
        // Restrict to admissible domain: positive amount and minSum to make deposit and collect meaningful
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(minSum > 0 && minSum <= amount);

        // Initialize the contract with the given MinSum
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Deploy a helper that will receive Ether and then call Collect on itself via c
        CollectHelper helper = new CollectHelper();

        // Fund the helper with the exact amount needed for the deposit + self-call
        vm.deal(address(helper), amount);

        // Helper sends Ether to c via fallback (which calls Deposit), then tries to collect
        bool success = helper.trigger(address(c), amount);

        // The rule: after a successful trigger, c's balance of the helper must be 0
        // (deposited and then collected the full amount). The buggy version never records
        // the deposit, so Collect reverts and success is false.
        assertTrue(success && c.balances(address(helper)) == 0);
    }
}

// Adversarial helper: receives Ether, sends it to C via a low-level call to trigger Deposit,
// then immediately calls Collect to withdraw the same amount.
contract CollectHelper {
    function trigger(address target, uint256 amount) external returns (bool) {
        // Send Ether to C, triggering the fallback -> Deposit
        (bool ok, ) = target.call{value: amount}("");
        if (!ok) return false;

        // Now call Collect on C as this contract (the sender)
        try C(target).Collect(amount) {
            return true;
        } catch {
            return false;
        }
    }
}

