pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address sender) public {
        vm.assume(sender != address(0) && sender != address(c));
        depositAmt = bound(depositAmt, 1, 100 ether);

        c.SetMinSum(1);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        uint256 balBefore = c.balances(sender);
        vm.deal(sender, depositAmt);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: depositAmt}("");
        require(ok, "Deposit via fallback failed");
        uint256 balAfterDeposit = c.balances(sender);

        collectAmt = bound(collectAmt, 1, balAfterDeposit);
        vm.prank(sender);
        try c.Collect(collectAmt) {}
        catch {}
        uint256 balAfterCollect = c.balances(sender);

        assertTrue(balAfterCollect == balAfterDeposit - collectAmt || balAfterCollect == balBefore);
    }
}

