pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetLogFile(address(new LogFile()));
        c.SetMinSum(100);
        c.Initialized();
    }
    function testFuzz_property(uint256 value, uint256 amt) public {
        amt = bound(amt, 100, address(c).balance + value);
        value = bound(value, 0, type(uint256).max - address(c).balance);
        vm.assume(address(c).balance + value >= amt);
        vm.deal(address(this), value);
        c.Deposit{value: value}();
        uint256 balBefore = address(c).balance;
        try c.Collect(amt) {
            assertEq(address(c).balance, balBefore - amt);
        } catch {
            assertEq(address(c).balance, balBefore);
        }
    }
}

