pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt, address user) public {
        // Admissible domain: deposit amounts are reasonable, collectAmt <= total balance to not revert legitimately
        vm.assume(user != address(0));
        vm.assume(deposit1 < type(uint128).max);
        vm.assume(deposit2 < type(uint128).max);
        uint256 total = deposit1 + deposit2;
        vm.assume(total >= deposit1); // no overflow in setup
        bound(collectAmt, 1, total);

        // Initialize contract
        c.Initialized();
        vm.deal(user, deposit1 + deposit2);

        // Deposit twice (mimics potential overflow scenario on buggy version)
        vm.prank(user);
        c.Deposit{value: deposit1}();
        vm.prank(user);
        c.Deposit{value: deposit2}();

        uint256 beforeBalance = c.balances(user);

        // Mint extra to cover collect call value (it calls user with _am)
        vm.deal(address(c), collectAmt);
        vm.prank(user);
        try c.Collect(collectAmt) {} catch {}

        uint256 afterBalance = c.balances(user);

        // General rule: after a collect, balance = initial_balance - collect_amount
        // Buggy version without overflow check can allow an underflow in Collect, making afterBalance huge
        assertTrue(afterBalance == beforeBalance - collectAmt);
    }
}

