pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 factor, uint256 otherBalance) public {
        // Admissible domain: depositAmount > 0 to trigger a state change; factor > 0 for meaningful multiplication;
        // bound values to avoid test rejection due to overflow in Solidity multiplication
        vm.assume(depositAmount > 0);
        vm.assume(factor > 0);
        bound(depositAmount, 1, type(uint128).max);
        bound(factor, 1, type(uint128).max);
        bound(otherBalance, 0, type(uint128).max);

        // Use a pre-funded EOA to deposit
        address actor = address(0x1234);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 senderBalance = c.balances(actor);
        // The reference contract ensures no overflow; thus balances[actor] * factor + otherBalance >= balances[actor]
        // The broken version can overflow, making the balance lower than expected
        unchecked {
            assertTrue(senderBalance * factor + otherBalance >= senderBalance);
        }
    }
}

